import{_ as a,c as n,o as s,a0 as l}from"./chunks/framework.C1J0Vcxi.js";const u=JSON.parse('{"title":"项目计划更新 — K3 (SpacemiT Key Stone) 实体板适配","description":"","frontmatter":{},"headers":[],"relativePath":"项目计划/项目计划-20260528.md","filePath":"项目计划/项目计划-20260528.md"}'),r={name:"项目计划/项目计划-20260528.md"};function e(d,t,i,o,p,c){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="项目计划更新-—-k3-spacemit-key-stone-实体板适配" tabindex="-1">项目计划更新 — K3 (SpacemiT Key Stone) 实体板适配 <a class="header-anchor" href="#项目计划更新-—-k3-spacemit-key-stone-实体板适配" aria-label="Permalink to &quot;项目计划更新 — K3 (SpacemiT Key Stone) 实体板适配&quot;">​</a></h1><blockquote><p>日期：2026-05-28（2026-05-30 修订） 变更：取消 VisionFive2 (JH7110) 移植计划，转投 <strong>SpacemiT K3</strong> 平台 修订：补充 RTOS 外设驱动规划、机器人应用 Demo 场景、8 月决赛演示方案</p></blockquote><h2 id="一、变更原因" tabindex="-1">一、变更原因 <a class="header-anchor" href="#一、变更原因" aria-label="Permalink to &quot;一、变更原因&quot;">​</a></h2><p>从 VisionFive2 (JH7110) 迁移到 SpacemiT K3，两个原因：</p><ol><li><strong>JH7110 核心内部资料不透明</strong> — U74 (SiFive) 为 IP 核，内部微架构文档封闭，底层调试和驱动优化受限</li><li><strong>K3 AI 性能远优于 VF2</strong> — 8× A100 提供 60 TOPS 算力，本地跑 30B 大模型；而 VF2 无任何 AI 加速</li></ol><p>此外 K3 内置双核 RT24 小核，<strong>RT24 专跑 rt-async（单核 M-mode），X100 大核跑 StarryOS</strong>，大小核物理隔离，实时性能不受 AI 负载影响。</p><table tabindex="0"><thead><tr><th>特性</th><th>VF2 方案 (废弃)</th><th><strong>K3 方案 (采用)</strong></th></tr></thead><tbody><tr><td>实时核</td><td>从 X100 大核中抠一个 hart</td><td><strong>RT24 独立小核</strong> (物理隔离)</td></tr><tr><td>大核负担</td><td>实时 hart 抢占 StarryOS 时间</td><td><strong>X100 全部 8 核跑 StarryOS/AI</strong></td></tr><tr><td>实时确定性</td><td>受乱序执行 + 缓存抖动影响</td><td><strong>6 级顺序核，确定性延迟</strong></td></tr><tr><td>AI 算力</td><td>无</td><td><strong>60 TOPS</strong> (8× A100, 本地跑 30B 模型)</td></tr><tr><td>核间 IPI</td><td>软件自实现 (CLINT MSIP)</td><td><strong>ACLINT MSIP</strong> (同机制，换地址)</td></tr><tr><td>中断控制器</td><td>PLIC + CLINT</td><td><strong>ACLINT + APLIC</strong> (RISC-V AIA)</td></tr><tr><td>UART</td><td>共享 1×</td><td><strong>独立：主域 17× + RT 域 6×</strong></td></tr><tr><td>GPIO</td><td>有限</td><td>5 组 (128 线) + RT 域独立 GPIO</td></tr><tr><td>内存</td><td>8GB LPDDR4</td><td><strong>最高 32GB LPDDR5</strong> (51 GB/s)</td></tr><tr><td>实时定时器</td><td>CLINT mtime</td><td><strong>专用 Timer 单元</strong> (多组) + Watchdog</td></tr></tbody></table><p><strong>核心优势</strong>：小核负责电机控制、传感器采集等微秒级实时任务；大核跑 AI 推理、视觉处理、StarryOS 用户态应用——两者通过本项目的 AMP 通信方案（ov-channels + ov-rpc）协作，延迟极低且互不干扰。</p><hr><h2 id="二、k3-硬件架构与地址映射摘要" tabindex="-1">二、K3 硬件架构与地址映射摘要 <a class="header-anchor" href="#二、k3-硬件架构与地址映射摘要" aria-label="Permalink to &quot;二、K3 硬件架构与地址映射摘要&quot;">​</a></h2><h3 id="_2-1-系统整体架构" tabindex="-1">2.1 系统整体架构 <a class="header-anchor" href="#_2-1-系统整体架构" aria-label="Permalink to &quot;2.1 系统整体架构&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                           应用层                                         │</span></span>
<span class="line"><span>│    机器人控制 · AI 推理 · 视觉识别 · 传感器采集 · 用户交互                 │</span></span>
<span class="line"><span>├──────────────────────────────┬──────────────────────────────────────────┤</span></span>
<span class="line"><span>│                              │                                          │</span></span>
<span class="line"><span>│   X100 × 8 (StarryOS)        │        RT24 × 1 (rt-async)              │</span></span>
<span class="line"><span>│   ┌────────────────────┐     │     ┌────────────────────┐               │</span></span>
<span class="line"><span>│   │  StarryOS 用户态 App   │     │     │  实时任务 (async)   │              │</span></span>
<span class="line"><span>│   │  AI 推理 · 规划决策  │     │     │  电机 · 传感器 · PWM│              │</span></span>
<span class="line"><span>│   └────────┬───────────┘     │     └────────┬───────────┘               │</span></span>
<span class="line"><span>│            │ mmap + ioctl    │              │                           │</span></span>
<span class="line"><span>│   ┌────────┴───────────┐     │              │                           │</span></span>
<span class="line"><span>│   │  /dev/rt_shm 驱动   │     │     ┌────────┴───────────┐             │</span></span>
<span class="line"><span>│   │  (StarryOS 内核)    │     │     │  Chip / TimerChip   │             │</span></span>
<span class="line"><span>│   └────────┬───────────┘     │     │  (rt-async platform) │             │</span></span>
<span class="line"><span>│            │                 │     └────────┬───────────┘             │</span></span>
<span class="line"><span>├────────────┼─────────────────┼──────────────┼──────────────────────────┤</span></span>
<span class="line"><span>│            │    本项目 AMP 通信方案          │                          │</span></span>
<span class="line"><span>│            │                 │              │                          │</span></span>
<span class="line"><span>│  ┌─────────┴─────────────────┴──────────────┴───────────────┐          │</span></span>
<span class="line"><span>│  │              ov-channels  (共享内存无锁通道)               │          │</span></span>
<span class="line"><span>│  │              ov-rpc       (postcard 序列化 RPC)            │          │</span></span>
<span class="line"><span>│  │              SHM 区域     (SRAM 512KB 或 DDR)             │          │</span></span>
<span class="line"><span>│  └─────────────────────────┬────────────────────────────────┘          │</span></span>
<span class="line"><span>│                            │ IPI 通知                                   │</span></span>
<span class="line"><span>│  ┌─────────────────────────┴────────────────────────────────┐          │</span></span>
<span class="line"><span>│  │  K3:  ACLINT MSIP 写寄存器 (与 QEMU CLINT MSIP 同机制)    │          │</span></span>
<span class="line"><span>│  └─────────────────────────┬────────────────────────────────┘          │</span></span>
<span class="line"><span>├────────────────────────────┼───────────────────────────────────────────┤</span></span>
<span class="line"><span>│              K3 SoC 硬件    │                                           │</span></span>
<span class="line"><span>│  ┌─────────────────────────┴────────────────────────────────┐          │</span></span>
<span class="line"><span>│  │  Main CPU Domain          │  RT CPU Domain                │          │</span></span>
<span class="line"><span>│  │  X100 × 8  (乱序, 2.4GHz) │  RT24 × 2  (顺序, RV64GC)    │          │</span></span>
<span class="line"><span>│  │  A100 × 8  (60 TOPS AI)   │  独立 UART × 6 / GPIO / PWM  │          │</span></span>
<span class="line"><span>│  │  8MB L2 共享缓存          │  独立中断源 (int_src[])       │          │</span></span>
<span class="line"><span>│  │  ACLINT + APLIC (AIA)     │  可访问 X100 域设备窗口       │          │</span></span>
<span class="line"><span>│  └───────────────────────────┴──────────────────────────────┘          │</span></span>
<span class="line"><span>│           共享内存: SRAM (512KB) · DDR (≤32GB LPDDR5)                  │</span></span>
<span class="line"><span>│  DDR (≤32GB LPDDR5) · UART (主域17×+RT域6×) · CAN ×10                  │</span></span>
<span class="line"><span>│  SPI ×6 · I2C ×9 · GPIO (128线) · PCIe ×8 · USB 3.0 ×5               │</span></span>
<span class="line"><span>│  GMAC ×4 · PWM ×30 · Mailbox ×16 · Spinlock ×32                       │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>数据流</strong>：用户态 App → mmap 共享内存 → ov-channels 写入消息 → ACLINT MSIP IPI 通知 RT24 → rt-async 异步任务处理 → 响应原路返回。</p><h3 id="_2-2-关键地址映射" tabindex="-1">2.2 关键地址映射 <a class="header-anchor" href="#_2-2-关键地址映射" aria-label="Permalink to &quot;2.2 关键地址映射&quot;">​</a></h3><h4 id="rt-域-rcpu-domain-—-rt-async-运行在-rt24-单核上-m-mode" tabindex="-1">RT 域 (RCPU Domain) — rt-async 运行在 RT24 单核上 (M-mode) <a class="header-anchor" href="#rt-域-rcpu-domain-—-rt-async-运行在-rt24-单核上-m-mode" aria-label="Permalink to &quot;RT 域 (RCPU Domain) — rt-async 运行在 RT24 单核上 (M-mode)&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模块</th><th>地址</th><th>大小</th><th>备注</th></tr></thead><tbody><tr><td>SRAM (512KB)</td><td><code>0xC080_0000</code></td><td>512KB</td><td>与主域 <code>0xC080_0000</code> 共享</td></tr><tr><td>X100 域设备窗口</td><td><code>0x8000_0000</code></td><td>~1GB</td><td>RT 域可访问主域设备</td></tr><tr><td>sys_ctrl</td><td><code>0xC088_0000</code></td><td>4KB</td><td>系统控制寄存器</td></tr><tr><td>R_UART0~5</td><td><code>0xC088_1000</code> ~ <code>0xC088_1500</code></td><td>256B/ea</td><td>RT 域专用 UART</td></tr><tr><td>R_GPIO</td><td><code>0xC088_9400</code></td><td>1KB</td><td>RT 域 GPIO</td></tr><tr><td>AON_TIMER1</td><td><code>0xC088_9000</code></td><td>1KB</td><td>Always-On 定时器</td></tr><tr><td>AON_TIMER2~4</td><td><code>0xC088_C800</code> ~ <code>0xC088_CA00</code></td><td>256B/ea</td><td>额外定时器</td></tr><tr><td>PWM0~9</td><td><code>0xC088_D100</code> ~ <code>0xC088_DA00</code></td><td>256B/ea</td><td>PWM 输出</td></tr><tr><td>R_SSP0~2 (SPI)</td><td><code>0xC088_5000</code> ~ <code>0xC088_5200</code></td><td>256B/ea</td><td>SPI 控制器</td></tr><tr><td>R_I2C0~1</td><td><code>0xC088_6000</code> ~ <code>0xC088_6100</code></td><td>256B/ea</td><td>I2C 控制器</td></tr><tr><td>R_MAILBOX</td><td><code>0xC076_0000</code></td><td>64KB</td><td>RT 域 Mailbox (SoC 提供，后续可选用)</td></tr><tr><td>DDR DRAM</td><td><code>0x01_0000_0000</code></td><td>64GB</td><td>通过地址映射访问主存</td></tr></tbody></table><h3 id="_2-3-中断架构" tabindex="-1">2.3 中断架构 <a class="header-anchor" href="#_2-3-中断架构" aria-label="Permalink to &quot;2.3 中断架构&quot;">​</a></h3><p>K3 使用 RISC-V AIA (Advanced Interrupt Architecture)：</p><ul><li><strong>ACLINT</strong>：每个 hart 的软件中断 (MSIP) + 定时器中断 (MTIMER) — 与 QEMU CLINT 同机制</li><li><strong>APLIC</strong>：外部中断控制器，MSI-only 输出，最多 1023 个中断源</li></ul><p>RT 域中断源（关键字段）：</p><table tabindex="0"><thead><tr><th>中断号</th><th>信号</th><th>用途</th></tr></thead><tbody><tr><td>int_src[8~10]</td><td>timer_{1,2,3}_irq</td><td>GP Timer 中断</td></tr><tr><td>int_src[17~21]</td><td>shub_uart_int[0~4]</td><td>RT UART 中断</td></tr><tr><td>int_src[49]</td><td>aud_gpio_int_ap</td><td>RT GPIO 中断</td></tr><tr><td>int_src[46~48]</td><td>timer2_{1,2,3}_irq</td><td>Timer2 中断</td></tr><tr><td>int_src[76~81]</td><td>timer3/4 中断</td><td>额外定时器</td></tr><tr><td>int_src[65~66]</td><td>mailbox_irq0[0~1]</td><td>Mailbox0 中断 (可选用)</td></tr><tr><td>int_src[67]</td><td>ap_spinlock_irq</td><td>Spinlock 解锁中断 (可选用)</td></tr></tbody></table><h3 id="_2-4-rt24-核心特性-rt-async-运行在此核" tabindex="-1">2.4 RT24 核心特性（rt-async 运行在此核） <a class="header-anchor" href="#_2-4-rt24-核心特性-rt-async-运行在此核" aria-label="Permalink to &quot;2.4 RT24 核心特性（rt-async 运行在此核）&quot;">​</a></h3><ul><li>基于 <strong>CVA6</strong> (OpenHW Group 开源核心)</li><li><strong>6 级顺序单发射</strong>流水线 — 确定性执行，适合实时</li><li>支持 <strong>RV64IMAFDC</strong> (RV64GC) 完整指令集</li><li>三级特权：<strong>M / S / U</strong> — rt-async 运行于 M-mode，独占整个 RT24 核</li><li>支持 <strong>SV39</strong> 虚拟内存 (ITLB + DTLB + PTW)</li><li>超低待机与运行功耗 — 不与大核争抢功耗预算</li><li><strong>独立外设集</strong> (RCPU Domain)：自有 UART × 6、GPIO、Timer、I2C、SPI 等，不与大核争用</li><li><strong>可通过地址窗口访问 X100 域设备</strong> (<code>0x8000_0000</code>) — 用于 Mailbox 等 SoC 共享资源</li><li><strong>与 X100 域共享 SRAM</strong> (<code>0xC080_0000</code>, 512KB) 和 DDR — 这是双核通过共享内存通信的基础</li><li>K3 有 2 个 RT24 核，计划只用 <strong>1 个跑 rt-async</strong>，另 1 个留做系统管理或备用</li></ul><hr><h2 id="三、修订后的项目阶段计划" tabindex="-1">三、修订后的项目阶段计划 <a class="header-anchor" href="#三、修订后的项目阶段计划" aria-label="Permalink to &quot;三、修订后的项目阶段计划&quot;">​</a></h2><h3 id="阶段一-rtos-内核完善-5月12日-6月15日" tabindex="-1">阶段一：RTOS 内核完善（5月12日 - 6月15日） <a class="header-anchor" href="#阶段一-rtos-内核完善-5月12日-6月15日" aria-label="Permalink to &quot;阶段一：RTOS 内核完善（5月12日 - 6月15日）&quot;">​</a></h3><ul><li>[x] <code>JoinHandle&lt;T&gt;</code></li><li>[ ] Mutex 优先级继承</li><li>[ ] 基础同步原语完善</li></ul><h3 id="阶段二-双内核通信-6月1日-6月30日" tabindex="-1">阶段二：双内核通信（6月1日 - 6月30日） <a class="header-anchor" href="#阶段二-双内核通信-6月1日-6月30日" aria-label="Permalink to &quot;阶段二：双内核通信（6月1日 - 6月30日）&quot;">​</a></h3><ul><li>[x] ov-channels 共享内存通信 (Notification + Message Queue)</li><li>[x] ov-rpc 调用框架（多通道、多调用模式：call / call_quiet / send / urgent）</li><li>[x] amp.toml 统一配置（地址自动生成）</li><li>[x] StarryOS rt_shm 设备驱动</li><li>[ ] 性能基准测试报告</li></ul><h3 id="阶段三-k3-实体板移植与驱动-6月15日-7月31日" tabindex="-1">阶段三：K3 实体板移植与驱动（6月15日 - 7月31日） <a class="header-anchor" href="#阶段三-k3-实体板移植与驱动-6月15日-7月31日" aria-label="Permalink to &quot;阶段三：K3 实体板移植与驱动（6月15日 - 7月31日）&quot;">​</a></h3><blockquote><p>取代原 VisionFive2 (JH7110) 移植计划</p></blockquote><h4 id="_3-1-平台基础设施" tabindex="-1">3.1 平台基础设施 <a class="header-anchor" href="#_3-1-平台基础设施" aria-label="Permalink to &quot;3.1 平台基础设施&quot;">​</a></h4><ul><li>[ ] K3 启动流程研究 <ul><li>[ ] RT24 核独立启动方式 (M-mode entry, 不依赖 X100 域)</li><li>[ ] RT24 与 X100 域的启动时序协调 (谁先启动？握手协议？)</li><li>[ ] 链接脚本适配 (RCPU 域地址映射，区别于 QEMU virt)</li><li>[ ] SRAM (512KB) 与 DDR 内存布局规划 — rt-async 代码放 SRAM 还是 DDR？</li></ul></li><li>[ ] RT24 裸机运行环境搭建 <ul><li>[ ] riscv64 target 配置 (RT24 为 RV64GC, 含 F/D 扩展 — 区别于 QEMU 的 imac)</li><li>[ ] 最小 M-mode 启动代码 (set up stack, mtvec, 跳入 rust main)</li><li>[ ] UART 控制台输出 (R_UART0 @ <code>0xC088_1000</code>, 16550 兼容)</li></ul></li></ul><h4 id="_3-2-核心驱动适配" tabindex="-1">3.2 核心驱动适配 <a class="header-anchor" href="#_3-2-核心驱动适配" aria-label="Permalink to &quot;3.2 核心驱动适配&quot;">​</a></h4><ul><li>[ ] 定时器驱动 <ul><li>[ ] AON Timer (替代 CLINT mtime，作为 rt-async 系统 tick)</li><li>[ ] GP Timer 1~3 (高精度 deadline / 周期任务)</li><li>[ ] 定时器频率获取与校准</li></ul></li><li>[ ] 中断控制器适配 <ul><li>[ ] 从 PLIC 切换到 <strong>APLIC</strong> (MSI-only 模式)</li><li>[ ] <strong>ACLINT MSIP</strong> — 与 QEMU CLINT MSIP 同机制，换基址即可</li><li>[ ] RT 域中断向量表 (int_src[] 映射)</li></ul></li></ul><h4 id="_3-3-外设驱动-机器人控制所需" tabindex="-1">3.3 外设驱动（机器人控制所需） <a class="header-anchor" href="#_3-3-外设驱动-机器人控制所需" aria-label="Permalink to &quot;3.3 外设驱动（机器人控制所需）&quot;">​</a></h4><blockquote><p>目标：为 RT24 核心提供控制机器人硬件的驱动能力， 使 rt-async 上的异步任务能直接操作电机、传感器等外设。</p></blockquote><ul><li>[ ] GPIO 驱动 (R_GPIO @ <code>0xC088_9400</code>) <ul><li>[ ] 基本 IO 读写</li><li>[ ] 中断模式 (int_src[49] aud_gpio_int_ap)</li></ul></li><li>[ ] PWM 驱动 (PWM0~9) <ul><li>[ ] 频率 / 占空比配置</li><li>[ ] 用于电机速度控制、舵机角度控制</li></ul></li><li>[ ] I2C 驱动 (R_I2C0~1 @ <code>0xC088_6000</code> ~ <code>0xC088_6100</code>) <ul><li>[ ] 主模式读写 (Master TX/RX)</li><li>[ ] 用于读取 IMU (加速度计/陀螺仪)、距离传感器等</li></ul></li><li>[ ] SPI 驱动 (R_SSP0~2 @ <code>0xC088_5000</code> ~ <code>0xC088_5200</code>) <ul><li>[ ] 全双工主模式</li><li>[ ] 用于高速传感器通信 (编码器、ADC 等)</li></ul></li><li>[ ] UART 驱动 (R_UART0~5) <ul><li>[ ] 中断收发 (int_src[17~21])</li><li>[ ] 用于调试串口 / 与外部模块通信 (蓝牙、GPS 等)</li></ul></li></ul><h4 id="_3-4-amp-通信方案迁移" tabindex="-1">3.4 AMP 通信方案迁移 <a class="header-anchor" href="#_3-4-amp-通信方案迁移" aria-label="Permalink to &quot;3.4 AMP 通信方案迁移&quot;">​</a></h4><p>本项目已实现的 AMP 通信架构（QEMU virt 上验证通过）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>X100 (StarryOS)                           RT24 (rt-async)</span></span>
<span class="line"><span>┌──────────────────┐                      ┌──────────────────┐</span></span>
<span class="line"><span>│  用户态 App       │                      │                  │</span></span>
<span class="line"><span>│  mmap(/dev/rt_shm)│◄────共享内存────────►│  ov-channels     │</span></span>
<span class="line"><span>│  ov-rpc / ioctl   │   (ov-channels)      │  ov-rpc          │</span></span>
<span class="line"><span>├──────────────────┤                      ├──────────────────┤</span></span>
<span class="line"><span>│  rt_shm 驱动      │◄──── IPI 通知 ──────►│  Chip::pend()    │</span></span>
<span class="line"><span>│  (mmap + ioctl)   │   CLINT MSIP (QEMU)  │  send_ipi_to_    │</span></span>
<span class="line"><span>└──────────────────┘                      │  StarryOS()         │</span></span>
<span class="line"><span>                                          └──────────────────┘</span></span></code></pre></div><p>迁移到 K3，<strong>整个通信方案不变</strong>，仅底层寄存器地址不同：</p><table tabindex="0"><thead><tr><th>层次</th><th>QEMU virt (当前)</th><th>K3 (迁移)</th></tr></thead><tbody><tr><td><strong>数据通路</strong></td><td>ov-channels (共享内存)</td><td>ov-channels — <strong>不变</strong></td></tr><tr><td><strong>RPC 框架</strong></td><td>ov-rpc (postcard 序列化)</td><td>ov-rpc — <strong>不变</strong></td></tr><tr><td><strong>用户态接口</strong></td><td><code>/dev/rt_shm</code> (mmap + ioctl)</td><td><code>/dev/rt_shm</code> — <strong>不变</strong></td></tr><tr><td><strong>IPI 通知</strong></td><td>CLINT MSIP 写寄存器</td><td><strong>ACLINT MSIP 写寄存器</strong> (同机制)</td></tr><tr><td><strong>定时器</strong></td><td>CLINT mtime</td><td><strong>AON Timer</strong> + GP Timer</td></tr><tr><td><strong>中断控制器</strong></td><td>PLIC</td><td><strong>APLIC</strong> (AIA)</td></tr><tr><td><strong>共享内存位置</strong></td><td>QEMU phys mem 固定区域</td><td><strong>SRAM (512KB)</strong> 或 DDR</td></tr></tbody></table><h3 id="阶段四-实验展示-7月15日-8月10日" tabindex="-1">阶段四：实验展示（7月15日 - 8月10日） <a class="header-anchor" href="#阶段四-实验展示-7月15日-8月10日" aria-label="Permalink to &quot;阶段四：实验展示（7月15日 - 8月10日）&quot;">​</a></h3><blockquote><p>向评委量化展示 RTOS 实时核的价值。</p></blockquote><blockquote><p>外设驱动（PWM/I2C/SPI）作为<strong>能力展示</strong>。</p></blockquote><h4 id="_4-1-rtos-侧-实时仿真控制任务" tabindex="-1">4.1 RTOS 侧：实时仿真控制任务 <a class="header-anchor" href="#_4-1-rtos-侧-实时仿真控制任务" aria-label="Permalink to &quot;4.1 RTOS 侧：实时仿真控制任务&quot;">​</a></h4><ul><li>[ ] 定义仿真 RPC 服务</li></ul><div class="language-ignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define_service! {</span></span>
<span class="line"><span>    pub ControlService {</span></span>
<span class="line"><span>        SET_TARGET:  0 =&gt; send  set_target(pos: i32);</span></span>
<span class="line"><span>        STOP:        1 =&gt; urgent stop();</span></span>
<span class="line"><span>        GET_STATE:   2 =&gt; call  get_state() -&gt; (i32, i32);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>[ ] 周期控制任务 (1kHz 软件仿真) <ul><li>[ ] rt-async 定时器驱动 1ms 周期循环</li><li>[ ] 每轮：读取目标 → PID 计算 → 记录输出与时间戳</li><li>[ ] 通过 UART 输出时间戳序列，供 StarryOS 侧分析抖动</li></ul></li><li>[ ] urgent 急停响应测试 <ul><li>[ ] StarryOS 侧发送 urgent → 测量 RT24 从收到 IPI 到停机的延迟</li><li>[ ] 对比 StarryOS 侧直接处理的延迟</li></ul></li></ul><h4 id="_4-2-starryos-侧-控制端-数据可视化" tabindex="-1">4.2 StarryOS 侧：控制端 + 数据可视化 <a class="header-anchor" href="#_4-2-starryos-侧-控制端-数据可视化" aria-label="Permalink to &quot;4.2 StarryOS 侧：控制端 + 数据可视化&quot;">​</a></h4><ul><li>[ ] 用户态控制 App <ul><li>[ ] 通过 ov-rpc <code>call</code> 下发目标 / 读取状态</li><li>[ ] 通过 ov-rpc <code>send</code> 持续推送设定值</li><li>[ ] 通过 ov-rpc <code>urgent</code> 触发急停</li></ul></li><li>[ ] 实时性数据采集与可视化 <ul><li>[ ] 采集 RTOS 侧的周期时间戳，绘制控制周期抖动图</li><li>[ ] 采集 IPC 往返延迟（StarryOS 发请求 → RTOS 响应 → StarryOS 收到）</li><li>[ ] 生成对比图表（详见 4.4）</li></ul></li></ul><h4 id="_4-3-跨核设备操控演示-驱动-rpc-联动" tabindex="-1">4.3 跨核设备操控演示（驱动 + RPC 联动） <a class="header-anchor" href="#_4-3-跨核设备操控演示-驱动-rpc-联动" aria-label="Permalink to &quot;4.3 跨核设备操控演示（驱动 + RPC 联动）&quot;">​</a></h4><blockquote><p>通过 StarryOS 侧 ov-rpc 远程操控 RT24 上的 UART / I2C 设备， 端到端验证&quot;Linux 下命令 → AMP RPC → RTOS 驱动 → 硬件响应&quot;全链路。</p></blockquote><ul><li>[ ] RPC 服务定义</li></ul><div class="language-ignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>define_service! {</span></span>
<span class="line"><span>    pub DeviceService {</span></span>
<span class="line"><span>        UART_WRITE: 0 =&gt; send  uart_write(data: [u8; 64]);</span></span>
<span class="line"><span>        UART_READ:  1 =&gt; call  uart_read() -&gt; [u8; 64];</span></span>
<span class="line"><span>        I2C_WRITE:  2 =&gt; send  i2c_write(addr: u8, data: [u8; 16]);</span></span>
<span class="line"><span>        I2C_READ:   3 =&gt; call  i2c_read(addr: u8, len: u8) -&gt; [u8; 16];</span></span>
<span class="line"><span>        STOP:       4 =&gt; urgent stop();</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><ul><li>[ ] UART 演示：StarryOS 用户态通过 ov-rpc 向 RT24 UART 发送字符串 → RT24 通过 R_UART 输出到串口终端 → 看到打印内容</li><li>[ ] I2C 演示：StarryOS 用户态通过 ov-rpc 读写 RT24 上的 AT24C02 EEPROM → 写入数据 → 读回验证 → 返回结果</li><li>[ ] 证明点：<strong>Linux 侧无需自带 I2C/UART 驱动，通过 RPC 即可透明操控 RT 域外设</strong></li></ul><h4 id="_4-4-实验设计-核心展示" tabindex="-1">4.4 实验设计（核心展示） <a class="header-anchor" href="#_4-4-实验设计-核心展示" aria-label="Permalink to &quot;4.4 实验设计（核心展示）&quot;">​</a></h4><p><strong>核心问题：为什么需要 RTOS 实时核？</strong></p><p>通过<strong>对比实验</strong>回答，全部可在 K3 板上复现：</p><p><strong>实验一：控制周期确定性</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>描述</th><th>预期结果</th></tr></thead><tbody><tr><td>StarryOS 直接控制</td><td>用户态 timerfd 1ms 周期循环</td><td>抖动大 (100us~ms 级)，受调度/GC 影响</td></tr><tr><td><strong>RTOS 控制</strong></td><td>rt-async 定时器 1ms 周期循环</td><td><strong>抖动 &lt; 10us，确定性执行</strong></td></tr></tbody></table><ul><li>[ ] 两侧各跑 10000 个周期，导出时间戳</li><li>[ ] 绘制 jitter 直方图 / 时序图，直观对比</li></ul><p><strong>实验二：负载下实时性退化</strong></p><table tabindex="0"><thead><tr><th>步骤</th><th>操作</th><th>观察</th></tr></thead><tbody><tr><td>1</td><td>StarryOS 空闲，RTOS 运行控制循环</td><td>基线：RTOS 周期抖动极小</td></tr><tr><td>2</td><td>StarryOS 启动 CPU 压力测试 (stress-ng)</td><td><strong>RTOS 周期抖动不变</strong></td></tr><tr><td>3</td><td>StarryOS 启动 AI 推理负载</td><td><strong>RTOS 周期抖动仍不变</strong></td></tr><tr><td>4</td><td>对比：StarryOS 自己跑控制循环 + 同等负载</td><td>周期抖动急剧恶化</td></tr></tbody></table><ul><li>[ ] 证明物理隔离的核心价值：<strong>大核负载不影响小核实时性</strong></li></ul><p><strong>实验三：IPC 延迟</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>描述</th></tr></thead><tbody><tr><td><code>call</code> 延迟</td><td>StarryOS 发请求 → IPI → RTOS 处理 → IPI → StarryOS 收响应</td></tr><tr><td><code>urgent</code> 延迟</td><td>StarryOS 发急停 → IPI → RTOS 执行 → 测量端到端时间</td></tr><tr><td>吞吐量</td><td>连续 N 次 <code>call</code>，测平均延迟和 P99</td></tr></tbody></table><ul><li>[ ] 不同负载下的延迟分布（空闲 / CPU 压力 / AI 推理）</li><li>[ ] 证明 IPC 机制在负载下稳定</li></ul><h3 id="阶段五-决赛交付与答辩-8月10日-8月12日" tabindex="-1">阶段五：决赛交付与答辩（8月10日 - 8月12日） <a class="header-anchor" href="#阶段五-决赛交付与答辩-8月10日-8月12日" aria-label="Permalink to &quot;阶段五：决赛交付与答辩（8月10日 - 8月12日）&quot;">​</a></h3><ul><li>[ ] K3 板上稳定运行：<strong>X100 大核 (StarryOS) + RT24 小核 (rt-async 实时)</strong><ul><li>备选：若 K3 硬件未到，QEMU virt 演示 + K3 驱动代码展示</li></ul></li><li>[ ] 通过本项目的 AMP 通信方案（ov-channels + ov-rpc + 共享内存 + ACLINT IPI）实现跨核通信</li><li>[ ] 实验演示 <ul><li>[ ] 实验一：控制周期确定性对比</li><li>[ ] 实验二：负载下实时性不退化</li><li>[ ] 实验三：IPC 延迟与吞吐量</li><li>[ ] 自动化实验脚本一键复现</li></ul></li><li>[ ] 驱动能力展示 <ul><li>[ ] 跨核设备操控：StarryOS 通过 ov-rpc 远程读写 Rt-Async 的 UART / I2C (AT24C02)</li><li>[ ] PWM 波形 / UART 输出</li><li>[ ] 证明 RTOS 驱动层完整可用</li></ul></li><li>[ ] 实时性指标：RT24 抢占延迟、IPC 往返延迟、控制周期抖动、负载下退化程度</li></ul><hr><h2 id="四、参考资源" tabindex="-1">四、参考资源 <a class="header-anchor" href="#四、参考资源" aria-label="Permalink to &quot;四、参考资源&quot;">​</a></h2><ul><li><a href="https://cdn-resource.spacemit.com/file/chip/K3/k3_um_en.pdf" target="_blank" rel="noreferrer">K3 User Manual (PDF)</a> — 完整手册</li><li><a href="https://cdn-resource.spacemit.com/file/chip/K3/K3_brief_en.pdf" target="_blank" rel="noreferrer">K3 Brief (PDF)</a></li><li><a href="https://www.spacemit.com/community/document/info?nodepath=hardware/key_stone/k3/k3_docs/root_overview.md&amp;lang=zh" target="_blank" rel="noreferrer">K3 Overview (中文)</a></li><li>RISC-V AIA Specification — ACLINT + APLIC 规范</li><li><a href="https://github.com/openhwgroup/cva6" target="_blank" rel="noreferrer">CVA6 Open Source Core</a> — RT24 基于 CVA6</li></ul>`,74)])])}const g=a(r,[["render",e]]);export{u as __pageData,g as default};
